     "summary": "科顺股份(300737.SZ)公告称，公司董事会审议通过回购股份议案，拟使用自有资金及自筹资金(含股票回购专项贷款资金等)以集中竞价交易方式回购公司已发行的人民币普通股(A股)，回购资金总额不低于5000万元且不超过1亿元。本次回购的股份将用于股权激励或员工持股计划、维护公司价值及股东权益。 （文章来源：财联社）",
